package poll

import (
  "log"
  "time"
)

type Watcher struct {
  interval time.Duration
  out      chan<- Event
}

func New(out chan<- Event) *Watcher {
  return &Watcher{interval: 5 * time.Second, out: out}
}

func (w *Watcher) Start() {
  go func() {
    for {
      time.Sleep(w.interval)
      ev, err := w.fetch()
      if err != nil {
        log.Printf("poll: %v", err)
        continue
      }
      w.out <- ev
    }
  }()
}

