func (w *Watcher) Start(ctx context.Context) {
  t := time.NewTicker(w.interval)
  go func() {
    defer t.Stop()
    for {
      select {
      case <-ctx.Done():
        return
      case <-t.C:
        w.tick(ctx)
      }
    }
  }()
}

func (w *Watcher) tick(ctx context.Context) {
  ev, err := w.fetch()
  if err != nil {
    log.Printf("poll: %v", err)
    return
  }
  select {
  case w.out <- ev:
  case <-ctx.Done():
  }
}
